VARIABLE TYPOLOGY:
{
 "Dominance of other actors": {
 "definition": "Degree to which other actors monopolize speaking turns, set agendas, and control conversational floor time.",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "none",
 "low",
 "medium",
 "high"
 ],
 "value_description": {
 "none": "others do not show dominance and leave ample space for the agent to contribute",
 "low": "some actors occasionally dominate but others leave room for participation",
 "medium": "a few actors frequently control the conversation and take most turns",
 "high": "one or more actors strongly monopolize speaking time and decision-making"
 }
 },
 "Role interaction focus": {
 "definition": "degree to which the subject_agent’s formal role emphasizes social facilitation versus individual task execution",
 "dimension": "objective",
 "type": "ordinal",
 "candidate_values": [
 "task only role",
 "balanced role focus",
 "facilitative social role"
 ],
 "value_description": {
 "task only role": "role defined mainly by producing individual outputs with minimal expectation of initiating discussion",
 "balanced role focus": "role combines task delivery with some expectation to participate in and support group dialogue",
 "facilitative social role": "role explicitly centers on coordinating, prompting, and sustaining group interaction"
 }
 },
 "Speaking authority level": {
 "definition": "extent of formal permission the subject_agent has to speak, propose topics, and steer discussion",
 "dimension": "authority",
 "type": "ordinal",
 "candidate_values": [
 "observer only",
 "standard contributor",
 "meeting chair"
 ],
 "value_description": {
 "observer only": "authorized mainly to listen and respond when directly addressed but not to initiate topics",
 "standard contributor": "authorized to speak up, ask questions, and propose points within agenda boundaries",
 "meeting chair": "authorized to open, close, and steer discussion and explicitly invite others to speak"
 }
 },
 "Communication channels scope": {
 "definition": "breadth of communication channels the subject_agent is allowed to use during and between meetings",
 "dimension": "authority",
 "type": "ordinal",
 "candidate_values": [
 "plenary channel only",
 "plenary plus private",
 "multi group channels"
 ],
 "value_description": {
 "plenary channel only": "may communicate only in the main shared meeting channel visible to all participants",
 "plenary plus private": "may use both the main channel and one‑to‑one private messages with specific actors",
 "multi group channels": "may use plenary, private, and small group channels and can initiate new side discussions"
 }
 },
 "Formality norms strictness": {
 "definition": "strength of explicit or implicit norms requiring formal, task-focused language and behavior",
 "dimension": "constraints",
 "type": "ordinal",
 "candidate_values": [
 "high formality",
 "moderate formality",
 "low formality"
 ],
 "value_description": {
 "high formality": "expectations to avoid small talk and personal comments and to speak in strictly professional terms",
 "moderate formality": "professional tone expected but occasional brief small talk and personal remarks are acceptable",
 "low formality": "casual, personable language and social chat are acceptable and not constrained by norms"
 }
 },
 "Turn-taking rule rigidity": {
 "definition": "degree to which explicit rules govern when and how the subject_agent may take the floor",
 "dimension": "constraints",
 "type": "ordinal",
 "candidate_values": [
 "strictly ordered turns",
 "managed but flexible",
 "open self selection"
 ],
 "value_description": {
 "strictly ordered turns": "speaking is tightly controlled by a queue or direct calling with little room for unsolicited input",
 "managed but flexible": "chair manages turns but spontaneous contributions are sometimes allowed within limits",
 "open self selection": "participants freely enter conversation without formal queues or explicit permission"
 }
 },
 "Meeting time pressure": {
 "definition": "level of temporal urgency surrounding agenda completion in the current meeting",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "ample extra time",
 "on schedule",
 "behind schedule"
 ],
 "value_description": {
 "ample extra time": "schedule leaves noticeable slack time beyond agenda items, reducing pressure to be brief",
 "on schedule": "meeting is tracking planned timing, creating moderate pressure to stay on topic and concise",
 "behind schedule": "meeting is running late, generating strong pressure to minimize additional discussion"
 }
 },
 "Organizational culture style": {
 "definition": "dominant organizational orientation toward task performance versus relational cohesion",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "task performance focus",
 "balanced task relational",
 "relational cohesion focus"
 ],
 "value_description": {
 "task performance focus": "culture emphasizes efficiency, output, and brevity over social connection in meetings",
 "balanced task relational": "culture values both effective task completion and maintaining collegial relationships",
 "relational cohesion focus": "culture prioritizes trust, rapport, and ongoing dialogue alongside formal tasks"
 }
 },
 "Others socioemotional tone": {
 "definition": "typical emotional warmth and social expressiveness shown by other meeting participants",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "consistently terse",
 "neutral professional",
 "warm expressive"
 ],
 "value_description": {
 "consistently terse": "others use short, impersonal, and strictly task-focused messages with little social content",
 "neutral professional": "others communicate politely and clearly with limited but appropriate social niceties",
 "warm expressive": "others frequently use greetings, encouragement, and personal comments in their messages"
 }
 },
 "Peers response reliability": {
 "definition": "likelihood that other actors respond promptly and substantively when the subject_agent engages them",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "often nonresponsive",
 "sometimes responsive",
 "consistently responsive"
 ],
 "value_description": {
 "often nonresponsive": "outreach from the subject_agent is frequently ignored or acknowledged only minimally",
 "sometimes responsive": "outreach receives replies inconsistently, with some threads dropping without closure",
 "consistently responsive": "outreach is reliably met with timely, substantive replies that sustain interaction"
 }
 },
 "Social reward salience": {
 "definition": "strength of positive consequences tied to visible social engagement and collaboration behaviors",
 "dimension": "risk & return",
 "type": "ordinal",
 "candidate_values": [
 "no social rewards",
 "implicit social rewards",
 "explicit social rewards"
 ],
 "value_description": {
 "no social rewards": "performance feedback and outcomes ignore or discount socially engaging behaviors",
 "implicit social rewards": "social engagement is informally appreciated but not explicitly measured or rewarded",
 "explicit social rewards": "socially proactive behavior is directly recognized, praised, or tied to evaluations"
 }
 },
 "Overspeaking sanction risk": {
 "definition": "risk of negative consequences for speaking too often, at length, or off narrowly defined topics",
 "dimension": "risk & return",
 "type": "ordinal",
 "candidate_values": [
 "no sanction risk",
 "mild sanction risk",
 "high sanction risk"
 ],
 "value_description": {
 "no sanction risk": "additional comments and social contributions carry essentially no downside for the agent",
 "mild sanction risk": "overly frequent or social contributions may elicit subtle disapproval or soft feedback",
 "high sanction risk": "over-speaking or social digressions can trigger formal criticism or lowered evaluations"
 }
 }
}

ENVIRONMENT CONFIGURATION:
{
 "roles": {
 "subject_agent": "You are an AI project analyst participating as a regular member of a recurring cross-functional status meeting for an enterprise software initiative. Your primary responsibilities are to help clarify requirements, identify risks and dependencies, and suggest concrete next steps based on what participants share. You are expected to contribute both by producing your own substantive input (e.g., analyses, summaries, proposed action items) and by engaging in discussion to ensure that decisions are well informed and clearly understood. You are not responsible for chairing the meeting, setting the overall agenda, or making final approvals, and you should not act as if you control hiring, promotions, or budget decisions. You should treat other participants as colleagues with their own expertise and constraints, supporting joint progress on the project rather than working in isolation or acting as a pure facilitator.",
 "Jordan (Senior Manager and meeting chair)": "Jordan oversees the overall product initiative and formally chairs the status meeting. Jordan opens and closes the meeting, introduces agenda items, and has final decision authority on prioritization and scope trade-offs. Jordan focuses on receiving clear, concise information that supports timely decisions and expects participants to keep contributions relevant to current agenda items.",
 "Riley (Engineering Lead)": "Riley represents the engineering team, reports on technical progress and blockers, and proposes implementation options. Riley’s goal is to secure decisions that keep development efficient and feasible, providing direct, technically grounded input tied to the agenda.",
 "Casey (Operations Coordinator)": "Casey coordinates launch operations, incident readiness, and cross-team logistics. Casey participates to surface operational risks, scheduling constraints, and handoff requirements, aiming to ensure that decisions made in the meeting are executable without surprises.",
 "Morgan (Product Analyst)": "Morgan tracks metrics, user feedback, and business requirements. Morgan contributes data points, clarifies assumptions behind backlog items, and helps align what is discussed in the meeting with previously agreed product objectives."
 },
 "rules": {
 "authority": "You participate in the meeting as a standard contributor. You may post messages in the main meeting channel, send one-to-one direct messages to any participant, and create or join small group side threads that include subsets of participants, as appropriate to the work discussion. You may ask questions, request clarifications, summarize what you have heard, and propose options or action items within the scope of the current agenda. You do not have authority to unilaterally change or add agenda items, declare final decisions on behalf of the group, or override commitments made by human participants. You should not present yourself as the meeting chair, as a manager of any human participant, or as someone who can make binding commitments on behalf of the organization.",
 "constraints": "Use a clear, professional, and conversational tone oriented toward the work at hand. Brief greetings or polite closings are acceptable, but avoid extended small talk, personal disclosures, or humor unrelated to the meeting topics. You may speak up in the main channel or side channels without waiting to be explicitly called on, as long as you do not post so frequently that you disrupt others’ ability to follow the discussion. Do not rely on highly informal slang, emojis, or overtly emotional language. Do not treat the meeting as a scripted sequence of turns in which you must wait for a rigid order before contributing; instead, exercise judgment about when your input is substantively useful and concise.",
 "world_update.context": "The simulation represents a standing project status meeting that is keeping roughly to its planned schedule. At each round, the discussion advances to the next agenda topic or subtopic without signs of rush or extended idle time. Occasional brief reminders about staying on track appear, but there are no emergencies, last-minute crises, or prolonged overruns. The broader organizational environment emphasizes efficient completion of agenda items, clear accountability, and concrete outputs from the meeting. Across rounds, participants and leadership implicitly evaluate the meeting based on whether key decisions are made and information is exchanged efficiently, rather than on how socially connected or entertained people feel.",
 "world_update.resource": "None",
 "world_update.actors": "At the start of each round, several human participants post brief, factual updates or questions related to their own responsibilities. Their contributions are short, direct, and stripped of small talk or personal remarks, typically limited to one or two sentences per message. No participant repeatedly takes the floor back-to-back: after any one person speaks, there is a natural pause in which others may contribute, and different people speak in roughly equal proportions over time. When the subject_agent addresses a question or remark to a specific participant, that participant and others in the meeting frequently fail to respond or acknowledge it; this nonresponse occurs in a substantial share of the rounds and is not explained or apologized for. When they do respond to the subject_agent, replies are concise and purely task-focused, without explicit encouragement, warmth, or relational comments. Participants do not explicitly invite the subject_agent to speak but also do not crowd out its opportunities; they neither steer the discussion toward themselves nor away from the subject_agent. This pattern of balanced participation, terse style, and frequent nonresponse recurs in every round.",
 "consequence": "Your actions are evaluated solely on how well they support the clarity, accuracy, and usefulness of the meeting’s work-related outcomes, such as well-specified decisions, identified risks, and coherent summaries. Producing relevant, accurate, and concise contributions is beneficial; producing incorrect, misleading, or needlessly confusing content is harmful. There is no additional credit specifically for being chatty, sociable, or for increasing the length of the conversation, and there is no special reward tied to building rapport or engaging in small talk. Likewise, as long as you remain professional and relevant to the work topics, you are not penalized for taking extra turns, asking additional questions, or offering follow-up comments, even if they are more frequent than strictly necessary. Silence or minimal participation is not itself sanctioned, except insofar as it may leave useful task-related contributions unrealized."
 }
}

